const D = { energy:.6, scale:1, density:.5, speed:1, hue:28, x:.5, y:.54, run:.5, style:'archive', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'engraving'), dk = (sty === 'chiaroscuro');

// ---- the camera TRUCKS SIDEWAYS: aisles sweep past, each opening a deep vista.
//      Stacks keyed on ABSOLUTE index -> the rhythm never repeats.
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.085 + .10*K.intensity + .095*P.energy);
const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.26;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const SX = u*.62;                               // stack pitch across, FIXED
const SW = SX*(.44 - .15*cl(P.density,0,1));    // denser => thinner stacks => more aisles read
const SH = u*.78*P.scale, CH = u*1.02*P.scale, eh = u*.30;
const AW = u*.62;                               // cross-aisle the camera walks
const RUN = u*(2.2 + 3.6*cl(P.run,0,1));        // how deep the stacks run
const NS = 4 + Math.round(cl(P.density,0,1)*2); // stacks either side of the camera

const camX = S.z*SX;
const camZ = -AW - u*.06*dC*P.energy;
const camY = -(eh + u*.018*dB*P.energy);
const yaw = .028*dA*P.energy + .016*Math.sin(K.t*.151+1.4);
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.06;
const vcx = cl(P.x,.15,.85)*width, vcy = cl(P.y,.3,.78)*height;
const Z0 = 0, Z1 = RUN;
const ic = Math.round(S.z);

// a reading lamp wanders the stacks on incommensurate rates
const lx0 = S.z + 1.7*Math.sin(K.t*.053) + .8*Math.sin(K.t*.131+1.9);

// ---- projection ---------------------------------------------------------------
const AXa = new Float64Array(10), AYa = new Float64Array(10), AZa = new Float64Array(10);
const BXa = new Float64Array(14), BYa = new Float64Array(14);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AXa[i] = X*ca - Z*sa; AYa[i] = Y; AZa[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZa[i], bz = AZa[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BXa[m] = vcx + f*AXa[i]/az; BYa[m] = vcy + f*AYa[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BXa[m] = vcx + f*(AXa[i]+(AXa[j]-AXa[i])*tt)/NEAR;
      BYa[m] = vcy + f*(AYa[i]+(AYa[j]-AYa[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BXa[i], BYa[i]); endShape(CLOSE);
  return true;
}
function pt2(X,Y,Z){
  const dx = X-camX, dy = Y-camY, dz = Z-camZ;
  const rz = dx*sa + dz*ca;
  if (rz <= NEAR) return null;
  return [vcx + f*(dx*ca - dz*sa)/rz, vcy + f*dy/rz, rz];
}

// ---- tone tables ---------------------------------------------------------------
function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = paper ? [40, 6, 90] : wire ? [212, 58, 20] : dk ? [HU, 14, 7]
           : sty === 'vault' ? [186, 8, 30] : [(HU+4)%360, 30, 22];
const fogA = (paper||wire) ? .28 : .72;
function tone(v, tv){
  if (paper) return [40, 5 + 4*tv, cl(97 - 52*(1-v), 40, 97)];
  if (wire)  return [212, 60, cl(11 + 10*v, 7, 30)];
  if (dk)    return [HU, cl(26 - 14*v, 0, 30), cl(2 + 90*Math.pow(v,1.9), 1, 96)];
  if (sty === 'vault') return [cl(188 - 12*v, 168, 200), cl(12 - 6*v + 4*tv, 1, 16), cl(9 + 78*v, 4, 95)];
  return [cl(HU + 6 - 8*v + 6*tv, 8, 46), cl(44 - 18*v + 8*tv, 6, 56), cl(7 + 74*v, 4, 93)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a);
  else if (paper) stroke(30, 20, 14, a);
  else stroke((HU+2)%360, 16, 82, a*.30);
}
const LTH = sty === 'vault' ? 172 : dk ? HU : (HU+8)%360;

// ---- ceiling + floor of the cross-aisle (banded) --------------------------------
noStroke();
const NBD = 30;
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1), c = tone(.06 + .17*s, fr(i*3.1));
  fill(c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.6, 0, 100));
  rect(0, s*vcy - 1.5, width, vcy/NBD + 3);
}
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1), c = tone(.24 + .16*s, fr(i*7.7+11));
  fill(c[0], c[1], cl(c[2] + (fr(i*9.1+3)-.5)*2.2, 0, 100));
  rect(0, vcy + s*(height-vcy) - 1.5, width, (height-vcy)/NBD + 3);
}

// ---- the aisles: each is a portal we CLIP to, then paint a deep vista through ----
for (let d2 = NS; d2 >= 0; d2--){
  for (let sgn2 = 0; sgn2 < 2; sgn2++){
    if (d2 === 0 && sgn2 === 1) continue;
    const a2 = ic + (sgn2 ? -d2 : d2);            // aisle between stack a2 and a2+1
    const xL = a2*SX + SW*.5, xR = (a2+1)*SX - SW*.5;
    if (xR - xL < u*.01) continue;
    // the portal = the aisle opening at Z0
    const q0 = pt2(xL, -SH, Z0), q1 = pt2(xR, -SH, Z0), q2 = pt2(xR, 0, Z0), q3 = pt2(xL, 0, Z0);
    if (!q0 || !q1 || !q2 || !q3) continue;
    if (Math.max(q0[0],q1[0]) < -2 || Math.min(q0[0],q1[0]) > width+2) continue;
    const open = cl(1 - Math.abs((xL+xR)*.5 - camX)/(SX*1.7), 0, 1);  // how square-on we are

    drawingContext.save();
    drawingContext.beginPath();
    drawingContext.moveTo(q0[0], q0[1]); drawingContext.lineTo(q1[0], q1[1]);
    drawingContext.lineTo(q2[0], q2[1]); drawingContext.lineTo(q3[0], q3[1]);
    drawingContext.closePath(); drawingContext.clip();

    // aisle floor
    if (!wire){
      const c = mixc(tone(.20, .4), HAZE, .3*fogA); noStroke();
      fill(c[0], c[1], c[2], 100);
      poly([xL, 0, Z0, xR, 0, Z0, xR, 0, Z1, xL, 0, Z1]);
    }
    // the lit window at the dead end of every aisle — the accent at the VP
    const wv = cl(46 + 46*gl*(.6 + .4*Math.sin(K.t*.23 + a2*1.3)), 8, 97);
    const ec = wire ? null : paper ? [40, 6, 95] : dk ? [HU, 10, wv] : [LTH, sty==='vault'?12:26, wv];
    if (ec){ noStroke(); fill(ec[0], ec[1], ec[2], 100); }
    else { noFill(); ink(74); }
    poly([xL, -SH*.86, Z1, xR, -SH*.86, Z1, xR, -SH*.16, Z1, xL, -SH*.16, Z1]);
    if (!wire && !paper){
      push(); blendMode(ADD); noStroke();
      fill(LTH, 24, 100, cl(3.0 + 6.0*gl*open, 0, 18));
      poly([xL, -SH, Z1-RUN*.5, xR, -SH, Z1-RUN*.5, xR, 0, Z1-RUN*.5, xL, 0, Z1-RUN*.5]);
      pop(); blendMode(BLEND);
    }

    // the two walls of books
    for (let wi=0; wi<2; wi++){
      const wx = wi ? xR : xL;
      const facing = wi ? (camX < xR) : (camX > xL);
      if (!facing) continue;
      const detail = (d2 <= 1);
      for (let r=0; r<4; r++){
        const y0 = -SH*(.94 - r*.225), y1 = -SH*(.94 - r*.225) + SH*.185;
        const rv = (.24 + .13*r) * (.5 + .55*gl);
        const c = mixc(tone(cl(rv,0,1), fr(r*3.7 + a2*2.1)), HAZE, .34*fogA);
        if (wire){ noFill(); ink(42); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
        poly([wx, y0, Z0, wx, y1, Z0, wx, y1, Z1, wx, y0, Z1]);      // shelf void behind the books
        if (!detail || wire) continue;
        // ---- book spines: walk Z outward, stop once they go sub-pixel
        const lit = cl(.30 + .58*Math.exp(-Math.pow((a2 + .5) - lx0, 2)*.55), 0, 1);
        let z = Z0 + RUN*.01, n2 = 0;
        while (z < Z1 && n2 < 15){
          const sw2 = RUN*(.020 + .030*fr(a2*13.3 + r*7.1 + n2*3.9));
          const pA = pt2(wx, y0, z), pB = pt2(wx, y0, z+sw2);
          if (!pA || !pB) break;
          if (Math.abs(pB[0]-pA[0]) < 1.1) break;
          const bh = .58 + .40*fr(a2*5.9 + r*11.7 + n2*2.3);
          const sh2 = fr(a2*3.1 + r*17.3 + n2*5.1);
          let bc;
          if (paper) bc = [40, 8, cl(88 - 44*sh2, 34, 94)];
          else if (dk) bc = [HU, cl(20 - 10*sh2, 0, 24), cl(3 + 76*lit*(.4+.6*bh), 1, 92)];
          else if (sty === 'vault') bc = [cl(184 + 16*sh2, 170, 205), cl(6 + 10*sh2, 2, 18), cl(16 + 58*lit*(.5+.5*bh), 6, 92)];
          else bc = [cl((HU - 16 + 300*Math.pow(sh2, 3.1))%360, 0, 359), cl(24 + 40*sh2, 10, 62), cl(14 + 56*lit*(.45+.6*bh), 6, 88)];
          bc = mixc(bc, HAZE, .30*fogA);
          noStroke(); fill(bc[0], bc[1], bc[2], 100);
          const yt = y1 - (y1-y0)*bh;
          poly([wx, yt, z, wx, y1, z, wx, y1, z+sw2*.86, wx, yt, z+sw2*.86]);
          if (sh2 > .74){                                   // a gilt title band
            const gc = mixc(paper ? [40,12,66] : [48, 62, cl(46 + 34*gl*lit, 12, 94)], HAZE, .3*fogA);
            fill(gc[0], gc[1], gc[2], 100);
            poly([wx, yt + (y1-yt)*.30, z, wx, yt + (y1-yt)*.44, z,
                  wx, yt + (y1-yt)*.44, z+sw2*.86, wx, yt + (y1-yt)*.30, z+sw2*.86]);
          }
          z += sw2; n2++;
        }
      }
      // shelf boards
      ink(paper ? 34 : 30); noFill(); strokeWeight(Math.max(1, u*.0013));
      for (let r=0; r<5; r++){ const yy = -SH*(.94 - r*.225) + SH*.185; poly([wx, yy, Z0, wx, yy, Z1]); }
    }
    // strip light running the aisle ceiling
    if (!wire && !paper){
      const fl = .62 + .38*Math.sin(K.t*.8 + a2*2.1);
      noStroke(); fill(LTH, sty==='vault'?10:18, cl(58 + 34*gl*fl, 8, 97), 100);
      poly([(xL+xR)*.5 - SX*.05, -SH*1.02, Z0, (xL+xR)*.5 + SX*.05, -SH*1.02, Z0,
            (xL+xR)*.5 + SX*.05, -SH*1.02, Z1, (xL+xR)*.5 - SX*.05, -SH*1.02, Z1]);
    }
    drawingContext.restore();
  }
}

// ---- the stack ends: coplanar at Z0, so they never overlap each other -----------
strokeWeight(Math.max(1, u*.0015));
for (let i = ic-NS-1; i <= ic+NS+1; i++){
  const x0 = i*SX - SW*.5, x1 = i*SX + SW*.5;
  const p = pt2(i*SX, 0, Z0);
  if (!p) continue;
  if (p[0] < -u*.4 || p[0] > width + u*.4) continue;
  const tv = fr(i*31.7);
  const lit = cl(.32 + .60*Math.exp(-Math.pow(i - lx0, 2)*.42), 0, 1);
  const c = tone(cl((.20 + .38*lit + .10*tv) * (.5+.55*gl), 0, 1), tv);
  if (wire){ noFill(); ink(66); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
  poly([x0, -SH, Z0, x1, -SH, Z0, x1, 0, Z0, x0, 0, Z0]);
  if (!wire){
    // a recessed panel + a card-catalogue label plaque — texture, not a flat fill
    const c2 = tone(cl((.13 + .28*lit + .08*tv) * (.5+.55*gl), 0, 1), tv);
    noStroke(); fill(c2[0], c2[1], c2[2], 100);
    poly([x0 + SW*.14, -SH*.94, Z0-1, x1 - SW*.14, -SH*.94, Z0-1,
          x1 - SW*.14, -SH*.08, Z0-1, x0 + SW*.14, -SH*.08, Z0-1]);
    const pc = paper ? [40, 10, 92] : [LTH, sty==='vault'?8:30, cl(52 + 34*gl*lit, 14, 95)];
    fill(pc[0], pc[1], pc[2], 100);
    poly([x0 + SW*.26, -SH*.80, Z0-2, x1 - SW*.26, -SH*.80, Z0-2,
          x1 - SW*.26, -SH*.70, Z0-2, x0 + SW*.26, -SH*.70, Z0-2]);
  }
  ink(paper ? 40 : 32); noFill();
  poly([x0, -SH, Z0, x1, -SH, Z0, x1, 0, Z0, x0, 0, Z0]);
}

// ---- cached grain + vignette -----------------------------------------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9000, Math.floor(width*height/235));
  for (let i=0;i<N;i++){
    const px = Math.abs((Math.sin(i*12.9898)*43758.5453)%1)*width;
    const py = Math.abs((Math.sin(i*78.233+2.1)*43758.5453)%1)*height;
    g.fill(0,0, (i%2) ? 100 : 0, paper ? 8 : 6);
    g.rect(px, py, 1.7, 1.7);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.095;
    g.fill(0,0,0, 1.2 + 4.0*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
